  "After a run it finds what went wrong or took extra work, and drafts an edit to its own instructions.":
    "Después de cada build, encuentra qué salió mal o qué costó trabajo de más y redacta una edición de sus propias instrucciones.",
  "After each finished build, send anonymous numbers: times, token counts, the model and whether it worked. Never your prompts, code, files or game names.":
    "Después de cada build terminado, envía números anónimos: tiempos, cantidad de tokens, el modelo y si funcionó. Nunca tus mensajes, código, archivos ni nombres de juegos.",
  "After the current work finishes": "Cuando termine el trabajo actual",
  "Agent is working. The first preview appears after it saves a screenshot.":
    "El agente está trabajando. La primera vista previa aparecerá cuando guarde una captura.",
  "Agents build in it in your Studio, and its scripts are files in this game's folder.":
    "Los agentes crean en él desde tu Studio, y sus scripts son archivos en la carpeta de este juego.",
  "Agents can edit and play it from this chat.": "Los agentes pueden editarlo y jugarlo desde este chat.",
  "Agents can look at an app’s window without it, never at password managers, System Settings, password prompts or Genex.":
    "Sin esto, los agentes pueden ver la ventana de una app, pero nunca gestores de contraseñas, Ajustes del Sistema, solicitudes de contraseña ni Genex.",
  "Agents didn’t start": "Los agentes no se iniciaron",
  "Agents only run in a protected space that Windows has to allow once. If you aren’t an administrator of this PC, ask one to enter their password when Windows asks, then press Set up.":
    "Los agentes solo se ejecutan en un espacio protegido que Windows tiene que permitir una vez. Si no eres administrador de este PC, pídele a uno que escriba su contraseña cuando Windows la pida y luego pulsa Configurar.",
  "Agents run their commands in Git Bash, which comes with Git for Windows. Install it from git-scm.com, then retry.":
    "Los agentes ejecutan sus comandos en Git Bash, que viene con Git for Windows. Instálalo desde git-scm.com y vuelve a intentarlo.",
  "Agents see its tools as {id}__…": "Los agentes ven sus herramientas como {id}__…",
  "Agents use it when a game needs a model and you haven’t asked for Genex.":
    "Los agentes lo usan cuando un juego necesita un modelo y no has pedido Genex.",
  "Agents work in your open place through it.": "Los agentes trabajan en tu lugar abierto a través de él.",
