  "It closed before it opened. Try again.": "Se cerró antes de abrirse. Inténtalo de nuevo.",
  "It couldn’t start on this Mac.": "No pudo iniciarse en este Mac.",
  "It ended before it could write up the build.": "Terminó antes de poder redactar el resumen del build.",
  "It finishes its own setup the first time it opens.": "Termina su propia configuración la primera vez que se abre.",
  "It hasn't started yet.": "Todavía no ha empezado.",
  "It installs when you relaunch; Genex tells you when it's ready.":
    "Se instalará al reiniciar; Genex te avisará cuando esté lista.",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "Está activado y seguirá así: su código nuevo se ejecuta en cuanto se carga, y cada una de sus herramientas te volverá a preguntar antes de ejecutarse.",
  "It isn’t on this Mac any more. Install it again.": "Ya no está en este Mac. Vuelve a instalarlo.",
  "It keeps downloading if you go back.": "Se sigue descargando si vuelves atrás.",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "Guarda tus scripts como archivos en la carpeta de este juego y le dice a Genex qué Studio es el de este juego.",
  "It kept getting this wrong, so it stopped to save your credits.":
    "Seguía fallando en esto, así que se detuvo para ahorrar tus créditos.",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "Sale de Jugar y de genex.games y vuelve a borradores. El enlace directo sigue funcionando, y las partidas y los me gusta se conservan si lo vuelves a publicar.",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "Puede que necesite los scripts de instalación de sus paquetes, que no se ejecutaron.",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "Integró el trabajo de esta parte sin el veredicto de un revisor. Los revisores puntúan las partes que se crean por pasos; esta se creó en una sola sesión.",
  "It merges into your build when the lead integrates this part.":
    "Se añadirá a tu build cuando el agente principal integre esta parte.",
  "It needs macOS {version} or later.": "Necesita macOS {version} o posterior.",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "Nunca usa gestores de contraseñas, Configuración de Windows, solicitudes de contraseña ni Genex.",
  "It ran into an error": "Hubo un error",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "Se ejecuta en momentos de Genex: {steps}; esos pasos no te preguntan antes.",
  "It runs with your access: Genex doesn't sandbox its code.": "Se ejecuta con tus permisos: Genex no aísla su código.",
  "It runs, but no reviewer compared it with the game you had.":
    "Funciona, pero ningún revisor lo comparó con el juego que tenías.",
  "It shows up here as soon as it runs.": "Aparecerá aquí en cuanto arranque.",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "Empieza desactivado: actívalo en Plugins; cada una de sus herramientas te preguntará antes de ejecutarse.",
